const now = new Date();
const today = now.toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
const dayOfWeek = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][now.getDay()];
const d = now.getDay();
const daysToMon = d === 0 ? 6 : d - 1;
const weekStart = new Date(now - daysToMon * 86400000).toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
return [{ json: { today, dayOfWeek, weekStart } }];

const items = $input.all();
const files = items
  .filter(i => i.json.Key && i.json.Key.endsWith('.md') && (i.json.Size || 0) > 0)
  .map(i => ({ key: i.json.Key, name: i.json.Key.split('/').pop(), sizeKB: Math.round((i.json.Size||0)/1024) }));
const { today, dayOfWeek, weekStart } = $('Set Dates').first().json;
return [{ json: { braindumpFiles: files, braindumpCount: files.length, today, dayOfWeek, weekStart } }];

const items = $input.all();
const { today, dayOfWeek, weekStart, braindumpFiles, braindumpCount } = $('Collect Brain Dumps').first().json;
const thisWeek = items
  .filter(i => {
    const key = i.json.Key || '';
    if (!key.endsWith('.md') || (i.json.Size || 0) === 0) return false;
    const name = key.split('/').pop();
    const m = name.match(/^(\d{4}-\d{2}-\d{2})/);
    return m && m[1] >= weekStart;
  })
  .map(i => ({ key: i.json.Key, name: i.json.Key.split('/').pop() }));
return [{ json: { today, dayOfWeek, weekStart, braindumpFiles, braindumpCount, processedThisWeek: thisWeek, processedCount: thisWeek.length } }];

const { today, weekStart, braindumpFiles, braindumpCount, processedThisWeek, processedCount } = $input.first().json;

let articlesContent = '';
try {
  const articlesDecoded = $('Decode Articles').first().json._text;
  articlesContent = articlesDecoded || '';
} catch(e) {}
const allUrls = articlesContent.split('\n').filter(l => /https?:\/\//.test(l));
const enriched = allUrls.filter(l => l.includes('[title::'));
const unenriched = allUrls.filter(l => !l.includes('[title::'));

// === Build prescriptive actions list ===
const actions = [];

if (braindumpCount > 0) {
  const fileList = braindumpFiles.slice(0, 5).map(f => f.name).join(', ');
  const more = braindumpCount > 5 ? ` (+${braindumpCount - 5} more)` : '';
  actions.push({
    severity: 'high',
    icon: '🧠',
    title: `Process ${braindumpCount} brain dump${braindumpCount > 1 ? 's' : ''} sitting in inbox`,
    detail: `${fileList}${more}`,
    command: 'set -a && source .env && set +a && python3 tools/process_brain_dump.py --verbose',
    why: 'Brain dumps in 00_Inbox/brain-dumps/ should be cleared by the daily 7AM processor. Anything still here means the cron skipped or the file landed after run.',
  });
}

if (unenriched.length > 20) {
  actions.push({
    severity: 'high',
    icon: '🔗',
    title: `Enrich ${unenriched.length} article URL${unenriched.length > 1 ? 's' : ''} — backlog growing`,
    detail: 'link-enricher runs hourly at :13 and processes 8 per pass. Backlog of >20 means hourly cadence is not keeping up.',
    command: '# Trigger link-enricher manually in n8n UI, OR raise batch size in workflows/n8n/link-enricher.json',
    why: 'Articles without [title::] tags show up as raw URLs in your Reading Queue.',
  });
} else if (unenriched.length > 0 && unenriched.length <= 20) {
  actions.push({
    severity: 'low',
    icon: '🔗',
    title: `${unenriched.length} unenriched article URL${unenriched.length > 1 ? 's' : ''} (catching up next hour)`,
    detail: 'Backlog within normal range — link-enricher will pick these up.',
  });
}

if (processedCount === 0) {
  actions.push({
    severity: 'high',
    icon: '⚠️',
    title: 'No tasks processed all week — brain-dump-processor likely broken',
    detail: 'Check n8n at http://192.168.1.121:5678 for failed brain-dump-processor-v2 executions.',
    command: 'set -a && source .env && set +a && python3 scripts/health_check.py --json',
    why: 'A healthy week should produce 1-3 processed files. Zero means the processor cron failed or was disabled.',
  });
}

const allClear = actions.length === 0;

// === Compute "spoiler" subject ===
const highCount = actions.filter(a => a.severity === 'high').length;
let subject;
if (allClear) {
  subject = `✅ Vault Health: ALL CLEAR — ${processedCount} tasks added this week`;
} else if (highCount > 0) {
  const headlineAction = actions.find(a => a.severity === 'high');
  subject = `⚠️ Vault Health: ${highCount} action${highCount > 1 ? 's' : ''} needed — ${headlineAction.title.substring(0, 60)}`;
} else {
  subject = `Vault Health: tidy — ${braindumpCount} dumps, ${unenriched.length} unenriched, ${processedCount} processed this week`;
}

// === HTML ===
function severityStyle(sev) {
  if (sev === 'high') return { bg: '#fef2f2', border: '#dc2626', text: '#991b1b', label: 'NOW' };
  if (sev === 'med')  return { bg: '#fff7ed', border: '#ea580c', text: '#9a3412', label: 'SOON' };
  return { bg: '#f0fdf4', border: '#16a34a', text: '#14532d', label: 'FYI' };
}

function actionCard(a) {
  const s = severityStyle(a.severity);
  let html = '<div style="background:' + s.bg + ';border-left:4px solid ' + s.border + ';padding:14px 16px;margin:8px 0;border-radius:0 4px 4px 0">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">';
  html += '<span style="font-weight:700;color:' + s.text + ';font-size:14px">' + a.icon + ' ' + a.title + '</span>';
  html += '<span style="background:' + s.border + ';color:white;padding:2px 8px;border-radius:3px;font-size:10px;font-weight:700;letter-spacing:1px">' + s.label + '</span>';
  html += '</div>';
  if (a.detail) {
    html += '<p style="margin:4px 0;font-size:12px;color:#4b5563">' + a.detail + '</p>';
  }
  if (a.command) {
    html += '<pre style="background:#1f2937;color:#a7f3d0;padding:10px 12px;border-radius:4px;font-size:11px;overflow-x:auto;margin:8px 0;white-space:pre-wrap;word-break:break-word">' + a.command.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre>';
  }
  if (a.why) {
    html += '<p style="margin:6px 0 0;font-size:11px;color:#6b7280;font-style:italic">' + a.why + '</p>';
  }
  html += '</div>';
  return html;
}

let html = '<div style="font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,sans-serif;max-width:680px;margin:0 auto;background:#f5f5f5;padding:0;line-height:1.5;color:#1a1a1a">';

// Apple Watch / accessibility preview
const previewLine = allClear
  ? `Vault healthy · ${processedCount} processed this week · ${enriched.length}/${allUrls.length} articles enriched`
  : `${highCount} action${highCount > 1 ? 's' : ''} needed · ${braindumpCount} dumps · ${unenriched.length} unenriched · ${processedCount} processed`;
html += '<noscript style="display:block;padding:8px 16px;background:#f3f4f6;color:#1f2937;font-size:12px">' + previewLine + '</noscript>';

// Header — color reflects status
const headerBg = allClear ? '#16a34a' : (highCount > 0 ? '#dc2626' : '#d97706');
html += '<div style="background:' + headerBg + ';color:white;padding:22px 20px;border-radius:8px 8px 0 0">';
html += '<h1 style="margin:0;font-size:20px;font-weight:700">' + (allClear ? '✅ Vault Health — All Clear' : '🛠️ Vault Health — Action Required') + '</h1>';
html += '<p style="margin:6px 0 0;font-size:13px;opacity:0.9">Week of ' + weekStart + ' · scanned ' + today + '</p>';
html += '</div>';

// DO THIS NOW (the headline section)
html += '<div style="padding:18px 20px;background:white;margin-top:2px">';
if (allClear) {
  html += '<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:6px;padding:18px;text-align:center">';
  html += '<p style="margin:0;font-size:15px;font-weight:600;color:#14532d">🎉 No actions needed.</p>';
  html += '<p style="margin:8px 0 0;font-size:12px;color:#15803d">Inbox clear · ' + enriched.length + '/' + allUrls.length + ' articles enriched · ' + processedCount + ' tasks processed this week.</p>';
  html += '</div>';
} else {
  html += '<h2 style="margin:0 0 10px;font-size:14px;color:#1a1a1a;text-transform:uppercase;letter-spacing:1.5px">📋 Do This Now</h2>';
  for (const a of actions) html += actionCard(a);
}
html += '</div>';

// Compact diagnostics footer (collapsible details)
html += '<div style="padding:14px 20px;background:#f9fafb;margin-top:2px">';
html += '<details><summary style="cursor:pointer;font-size:13px;font-weight:600;color:#374151;padding:6px 0">📊 Vault Diagnostics (raw counts)</summary>';
html += '<table style="width:100%;border-collapse:collapse;margin-top:10px;font-size:12px">';
html += '<tr><td style="padding:6px 0;color:#6b7280">Brain dumps in inbox</td><td style="text-align:right;font-weight:600">' + braindumpCount + '</td></tr>';
html += '<tr><td style="padding:6px 0;color:#6b7280">Article URLs queued</td><td style="text-align:right;font-weight:600">' + allUrls.length + ' (' + enriched.length + ' enriched / ' + unenriched.length + ' raw)</td></tr>';
html += '<tr><td style="padding:6px 0;color:#6b7280">Tasks processed this week</td><td style="text-align:right;font-weight:600">' + processedCount + '</td></tr>';
html += '</table>';

if (braindumpCount > 0) {
  html += '<p style="margin:12px 0 4px;font-size:11px;color:#6b7280;font-weight:600">Brain dumps waiting:</p>';
  html += '<ul style="margin:0;padding-left:20px;font-size:11px;color:#6b7280">';
  for (const f of braindumpFiles.slice(0, 8)) {
    html += '<li><code>' + f.name + '</code> (' + f.sizeKB + 'KB)</li>';
  }
  if (braindumpCount > 8) html += '<li>...and ' + (braindumpCount - 8) + ' more</li>';
  html += '</ul>';
}
if (unenriched.length > 0) {
  html += '<p style="margin:12px 0 4px;font-size:11px;color:#6b7280;font-weight:600">Unenriched URLs (sample):</p>';
  html += '<ul style="margin:0;padding-left:20px;font-size:11px;color:#6b7280">';
  for (const l of unenriched.slice(0, 6)) {
    html += '<li><code>' + l.slice(0, 90).replace(/</g, '&lt;') + '</code></li>';
  }
  if (unenriched.length > 6) html += '<li>...and ' + (unenriched.length - 6) + ' more</li>';
  html += '</ul>';
}

html += '</details></div>';

html += '<div style="background:#1a1a2e;color:#9ca3af;padding:12px 20px;border-radius:0 0 8px 8px;text-align:center;font-size:11px">';
html += 'Life OS Vault Health · runbook: <code>docs/RUNBOOK.md</code> · ' + today;
html += '</div>';
html += '</div>';

const badge = allClear ? 'HEALTHY' : (highCount > 0 ? 'ACTION' : 'OK');
return [{ json: {
  html, subject, today, badge,
  braindumpCount, unenrichedCount: unenriched.length, processedCount,
  actionCount: actions.length, highCount,
  bodyLength: html.length
} }];

const j = $input.first().json;
const log = JSON.stringify({
  workflow: 'vault-health-report', run_date: j.today,
  finished_at: new Date().toISOString(), status: 'success',
  badge: j.badge, braindump_count: j.braindumpCount,
  unenriched_articles: j.unenrichedCount, processed_this_week: j.processedCount
}, null, 2);
const buf = Buffer.from(log, 'utf-8');
const logKey = `99_System/logs/vault-health-report-${j.today}.json`;
return [{ json: { logKey }, binary: {
  data: { data: buf.toString('base64'), mimeType: 'application/json', fileName: logKey.split('/').pop(), fileExtension: 'json', fileSize: buf.length }
}}];

// Decode S3 binary (filesystem-v2) to plain JSON text for downstream cross-reference
let text = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  text = buf.toString('utf-8');
} catch(e) {}
return [{ json: { ...($input.first().json), _text: text } }];

// Parse the audit endpoint's response. The runner returns
// {exit_code, duration_ms, stdout_json, stdout_raw, stderr_tail, timed_out}.
// When the audit script printed valid JSON to stdout, stdout_json is the
// already-parsed object; otherwise stdout_raw carries the literal text.
const item = $input.first();
const exitCode = item.json.exit_code != null ? item.json.exit_code : -1;
const stderrTail = (item.json.stderr_tail || '').toString();
let summary = item.json.stdout_json;
if (!summary && item.json.stdout_raw) {
  try { summary = JSON.parse(item.json.stdout_raw); } catch (e) {}
}
if (!summary) {
  return [{ json: {
    audit_status: 'parse_error',
    parse_error: 'audit_stdout_unparseable',
    exitCode,
    raw_stderr_tail: stderrTail.split('\n').slice(-15).join('\n'),
    findings_count: 0,
    findings: [],
    findings_by_rule: {},
  }}];
}
return [{ json: {
  audit_status: summary.status,
  sources_scanned: summary.sources_scanned,
  receipts_scanned: summary.receipts_scanned,
  window_days: summary.window_days,
  findings_count: summary.findings_count,
  findings: summary.findings || [],
  findings_by_rule: summary.findings_by_rule || {},
  exitCode,
}}];
